import { Pattern } from "../pattern/pattern";
import { Device } from "../pattern/device";
import { checkSpanBounds, createSpanBounds } from "./spanBound";

import type { Configuration } from "../configuration";
import type { JConfiguration, JDevice } from "shared/json";
import type { Partition } from "../partition";
import type { SpanBounds } from "./spanBound";

//=================================================================
/**
 * {@link patternGenerator} takes the {@link JDevice}s generated by
 * {@link Partition}s and combine them into {@link Pattern}s.
 */
//=================================================================
export function* patternGenerator(
	config: Configuration, proto?: JConfiguration
): Generator<Pattern> {

	let protoSignature: string | undefined;
	if(proto && proto.patterns && proto.patterns.length) {
		if(typeof proto.index == "number") {
			for(const pattern of proto.patterns) {
				yield new Pattern(config, pattern.devices, true);
			}
			return;
		}

		const pattern = new Pattern(config, proto.patterns[0].devices, true);
		/* istanbul ignore else: debug */
		if(pattern.$valid) {
			const devices = pattern.$devices.map(device => device.toJSON());
			protoSignature = Device.$getSignature(devices);
			yield pattern;
		}
	}

	// Search for patterns
	const buffer: JDevice[] = new Array(config.$partitions.length);
	const bounds = createSpanBounds(config);
	const generator =
		recursiveDeviceGenerator(config.$partitions, bounds, 0, buffer);
	for(const devices of generator) {
		// Compare and skip prototype pattern
		if(protoSignature) {
			const signature = Device.$getSignature(devices);
			if(signature == protoSignature) {
				protoSignature = undefined; // No need to compare further
				continue;
			}
		}
		const pattern = new Pattern(config, devices);
		if(pattern.$valid) yield pattern;
	}
}

/**
 * Generate the combinations of {@link JDevice}s in order. The combinations
 * that cannot pass the {@link SpanBounds} are skipped as early as possible,
 * as the number of combinations grows exponentially with the number of
 * {@link Partition}s.
 */
function* recursiveDeviceGenerator(
	partitions: readonly Partition[], bounds: SpanBounds,
	depth: number, buffer: JDevice[]
): Generator<JDevice[]> {
	const partition = partitions[depth];
	for(const device of partition.$devices.$values()) {
		buffer[depth] = device;
		if(!checkSpanBounds(bounds, depth, buffer)) continue;
		if(depth + 1 < partitions.length) {
			yield* recursiveDeviceGenerator(
				partitions, bounds, depth + 1, buffer
			);
		} else {
			yield buffer.concat();
		}
	}
}
